import React, { useState, useRef, useEffect } from "react";
import { RecaptchaVerifier, signInWithPhoneNumber, ConfirmationResult } from "firebase/auth";
import { auth } from "@/lib/firebase";
import { useNavigate } from "@tanstack/react-router";
import { Smartphone, ArrowRight, Loader2, ArrowLeft } from "lucide-react";

declare global {
  interface Window {
    recaptchaVerifier: RecaptchaVerifier;
  }

  const grecaptcha: any;
}

export function PhoneAuth() {
  const navigate = useNavigate();
  const [step, setStep] = useState<"phone" | "otp">("phone");
  const [phone, setPhone] = useState("");
  const [otp, setOtp] = useState(["", "", "", "", "", ""]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [confirmationResult, setConfirmationResult] = useState<ConfirmationResult | null>(null);
  const otpRefs = useRef<(HTMLInputElement | null)[]>([]);

  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
  }, []);

  useEffect(() => {
    if (!isMounted) return;

    if (typeof window !== "undefined" && !window.recaptchaVerifier) {
      window.recaptchaVerifier = new RecaptchaVerifier(auth, "recaptcha-container", {
        size: "invisible",
      });
    }

    // Cleanup to prevent memory leaks on unmount/refresh
    return () => {
      if (typeof window !== "undefined" && window.recaptchaVerifier) {
        try {
          window.recaptchaVerifier.clear();

          window.recaptchaVerifier = undefined as any;
        } catch {
          // ignore cleanup errors
        }
      }
    };
  }, [isMounted]);

  if (!isMounted) return null;

  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    const cleanPhone = phone.replace(/\D/g, "");
    if (cleanPhone.length !== 10) {
      setError("Please enter a valid 10-digit mobile number");
      return;
    }

    setLoading(true);
    try {
      const phoneNumber = `+91${cleanPhone}`;
      const appVerifier = window.recaptchaVerifier;

      if (!appVerifier) {
        setError("Security verifier not ready. Please refresh the page.");
        setLoading(false);
        return;
      }

      const confirmation = await signInWithPhoneNumber(auth, phoneNumber, appVerifier);
      setConfirmationResult(confirmation);
      setStep("otp");

    } catch (err: any) {
      console.error("Phone Auth Error:", err);
      const errCode = err?.code || "";
      const errMsg = err?.message || "";

      const isBlocked =
        errCode === "auth/network-request-failed" ||
        errCode === "auth/captcha-check-failed" ||
        errCode === "auth/web-storage-unsupported" ||
        errMsg.includes("reCAPTCHA") ||
        errMsg.includes("network") ||
        errMsg.includes("Timeout") ||
        errMsg.includes("blocked");

      if (isBlocked) {
        setError(
          "Verification was blocked by your browser extension or shield. Please disable Ad-Blocker/Shields and try again.",
        );
      } else if (errCode === "auth/too-many-requests") {
        setError("Too many attempts. Please wait a few moments and try again.");
      } else if (errCode === "auth/invalid-phone-number") {
        setError("Invalid mobile number format. Please check the 10 digits.");
      } else if (errCode === "auth/quota-exceeded") {
        setError("SMS quota exceeded for today. Please try again later.");
      } else {
        setError(errMsg || "Failed to send OTP. Please try again.");
      }
    } finally {
      setLoading(false);
    }
  };

  const handleOtpChange = (index: number, value: string) => {
    if (!/^[0-9]*$/.test(value)) return;

    const newOtp = [...otp];
    // Take only the last character if multiple are pasted
    newOtp[index] = value.slice(-1);
    setOtp(newOtp);

    // Auto-focus next input
    if (value && index < 5) {
      otpRefs.current[index + 1]?.focus();
    }
  };

  const handleOtpKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Backspace" && !otp[index] && index > 0) {
      // Auto-focus previous input on backspace if current is empty
      otpRefs.current[index - 1]?.focus();
    }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    const otpCode = otp.join("");

    if (otpCode.length !== 6 || !confirmationResult) {
      setError("Please enter the complete 6-digit OTP");
      return;
    }

    setLoading(true);
    setError("");
    try {
      await confirmationResult.confirm(otpCode);
      // Successful login, redirect to dashboard
      navigate({ to: "/host/dashboard" });

    } catch (err: any) {
      console.error("OTP Verification Error:", err);
      const errCode = err?.code || "";
      if (errCode === "auth/invalid-verification-code") {
        setError("Incorrect OTP. Please enter the valid 6-digit code.");
      } else if (errCode === "auth/code-expired") {
        setError("OTP has expired. Please go back and request a new code.");
      } else {
        setError(err.message || "Verification failed. Please try again.");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="relative w-full max-w-md mx-auto z-10">
      {/* Hidden recaptcha container placed at the absolute root to avoid conditional re-rendering */}
      <div id="recaptcha-container" className="absolute pointer-events-none opacity-0" />

      {/* Ambient Apple Depth Glow strictly behind the auth container */}
      <div className="absolute inset-0 bg-emerald-500/10 blur-[80px] -z-10 pointer-events-none rounded-[2rem]" />

      <div className="bg-black/30 backdrop-blur-xl border border-white/10 rounded-[2rem] p-6 sm:p-8 shadow-2xl relative overflow-hidden">
        {error && (
          <div className="mb-4 p-3 bg-red-500/10 border border-red-500/50 rounded-xl text-red-500 text-sm text-center">
            {error}
          </div>
        )}

        {step === "phone" ? (
          <form onSubmit={handleSendOtp} className="space-y-6">
            <div className="space-y-2">
              <label
                htmlFor="phone"
                className="text-xs font-semibold text-slate-300 uppercase tracking-wider ml-2"
              >
                Mobile Number
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-6 flex items-center pointer-events-none">
                  <Smartphone className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  id="phone"
                  type="tel"
                  maxLength={10}
                  value={phone}
                  onChange={(e) => setPhone(e.target.value.replace(/\D/g, ""))}
                  className="w-full pl-24 pr-6 py-4 bg-black/30 backdrop-blur-xl border border-white/10 text-white rounded-[2rem] focus:outline-none focus:border-emerald-500 transition-all placeholder-slate-500"
                  placeholder="Enter 10 digit number"
                  autoComplete="off"
                />
                <div className="absolute inset-y-0 left-12 flex items-center pointer-events-none">
                  <span className="text-slate-400 pl-2 pr-3 border-r border-white/10 mr-2 text-sm font-medium">
                    +91
                  </span>
                </div>
              </div>
            </div>
            <button
              type="submit"
              disabled={loading || phone.length !== 10}
              className="bg-emerald-500 text-black font-bold rounded-full py-4 w-full hover:bg-emerald-400 active:scale-95 transition-all ease-[cubic-bezier(0.23,1,0.32,1)] flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                <>
                  Send OTP
                  <ArrowRight className="w-5 h-5" />
                </>
              )}
            </button>
          </form>
        ) : (
          <form onSubmit={handleVerifyOtp} className="space-y-6">
            <div className="text-center mb-6">
              <h3 className="text-xl font-bold text-white mb-2">Enter OTP</h3>
              <p className="text-sm text-slate-400">We've sent a 6-digit code to +91 {phone}</p>
            </div>

            <div className="flex justify-between gap-2 sm:gap-3">
              {otp.map((digit, index) => (
                <input
                  key={index}
                  ref={(el) => {
                    otpRefs.current[index] = el;
                  }}
                  type="text"
                  inputMode="numeric"
                  maxLength={1}
                  value={digit}
                  onChange={(e) => handleOtpChange(index, e.target.value)}
                  onKeyDown={(e) => handleOtpKeyDown(index, e)}
                  className="w-10 h-12 sm:w-12 sm:h-14 text-center text-xl sm:text-2xl font-bold bg-black/30 backdrop-blur-xl border border-white/10 text-white rounded-2xl focus:outline-none focus:border-emerald-500 transition-all"
                />
              ))}
            </div>

            <div className="pt-2">
              <button
                type="submit"
                disabled={loading || otp.join("").length !== 6}
                className="bg-emerald-500 text-black font-bold rounded-full py-4 w-full hover:bg-emerald-400 active:scale-95 transition-all ease-[cubic-bezier(0.23,1,0.32,1)] flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : "Verify & Continue"}
              </button>
            </div>

            <button
              type="button"
              onClick={() => {
                setStep("phone");
                setOtp(["", "", "", "", "", ""]);
                setError("");
              }}
              className="text-xs text-muted-foreground hover:text-white flex items-center gap-1 transition-colors mx-auto mt-4"
            >
              <ArrowLeft className="w-3 h-3" /> Change Phone Number
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

import { useState, useRef, useEffect } from "react";
import { motion, useMotionValue, useTransform, animate, AnimatePresence } from "framer-motion";
import { supabase } from "@/lib/supabase";
import * as z from "zod";

// Zod Schema for strict typing
const leadSchema = z.object({
  items: z.number().min(1),
  durationMonths: z.number().min(1),
  estimatedPrice: z.number().min(0),
  savings: z.number().min(0),
});

type LeadData = z.infer<typeof leadSchema>;

// Verified Kanpur Unit Economics
const PRICE_PER_BAG = 300;
const COMPETITOR_PRICE = 800; // Estimated generic warehousing competitor

export function SavingsCalculator() {
  const [items, setItems] = useState(2);
  const [duration, setDuration] = useState(3);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Motion values for real-time fluid number ticking
  const animatedCost = useMotionValue(items * duration * PRICE_PER_BAG);
  const animatedSavings = useMotionValue(items * duration * (COMPETITOR_PRICE - PRICE_PER_BAG));

  const displayCost = useTransform(
    animatedCost,
    (value) => `₹${Math.round(value).toLocaleString()}`,
  );
  const displaySavings = useTransform(
    animatedSavings,
    (value) => `₹${Math.round(value).toLocaleString()}`,
  );

  // Animate the ticking numbers whenever the sliders change
  useEffect(() => {
    const cost = items * duration * PRICE_PER_BAG;
    const savings = items * duration * (COMPETITOR_PRICE - PRICE_PER_BAG);

    animate(animatedCost, cost, { duration: 0.5, ease: [0.22, 1, 0.36, 1] });
    animate(animatedSavings, savings, { duration: 0.5, ease: [0.22, 1, 0.36, 1] });
  }, [items, duration, animatedCost, animatedSavings]);

  const handleSubmit = async () => {
    setLoading(true);
    setError(null);

    const leadData: LeadData = {
      items,
      durationMonths: duration,
      estimatedPrice: items * duration * PRICE_PER_BAG,
      savings: items * duration * (COMPETITOR_PRICE - PRICE_PER_BAG),
    };

    // 1. Zod Validation before backend hit
    const parsed = leadSchema.safeParse(leadData);
    if (!parsed.success) {
      setError("Invalid calculation data.");
      setLoading(false);
      return;
    }

    // 2. Push to Supabase Engine
    try {
      const { error: dbError } = await supabase.from("stash_leads").insert([
        {
          items: parsed.data.items,
          duration_months: parsed.data.durationMonths,
          estimated_price: parsed.data.estimatedPrice,
          savings: parsed.data.savings,
          created_at: new Date().toISOString(),
        },
      ]);

      if (dbError) throw dbError;

      // 3. Trigger UI success state
      setIsSubmitted(true);

    } catch (err: any) {
      setError(err.message || "Failed to secure stash. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full bg-transparent p-4 flex items-center justify-center relative z-10">
      <AnimatePresence mode="wait">
        {!isSubmitted ? (
          <motion.div
            key="calculator"
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.05 }}
            transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
            className="w-full max-w-lg bg-white/5 backdrop-blur-2xl border border-white/10 rounded-3xl p-8 shadow-2xl"
          >
            <h2
              className="text-3xl font-bold text-student-primary mb-2 text-center"
              style={{ fontFamily: "GTA6-Heading" }}
            >
              Savings Matrix
            </h2>
            <p className="text-white/60 text-center mb-8">
              Calculate your dead-rent savings instantly.
            </p>

            <div className="space-y-8">
              <FramerSlider
                label="Number of Bags/Boxes"
                min={1}
                max={10}
                value={items}
                onChange={setItems}
                suffix=" items"
              />
              <FramerSlider
                label="Storage Duration"
                min={1}
                max={12}
                value={duration}
                onChange={setDuration}
                suffix=" months"
              />
            </div>

            <div className="mt-10 grid grid-cols-2 gap-4">
              <div className="bg-black/30 rounded-2xl p-4 border border-white/5 text-center">
                <p className="text-white/60 text-sm mb-1">Total Cost</p>
                <motion.p className="text-2xl font-bold text-white tracking-tight">
                  {displayCost}
                </motion.p>
              </div>
              <div className="bg-student-primary/10 rounded-2xl p-4 border border-student-primary/20 text-center">
                <p className="text-student-primary/80 text-sm mb-1 font-semibold uppercase tracking-wider text-[10px]">
                  Total Savings
                </p>
                <motion.p className="text-2xl font-bold text-student-primary tracking-tight">
                  {displaySavings}
                </motion.p>
              </div>
            </div>

            {error && <p className="text-red-400 text-sm text-center mt-4">{error}</p>}

            <button
              onClick={handleSubmit}
              disabled={loading}
              className="mt-8 w-full bg-student-primary text-black font-bold py-4 px-6 rounded-xl transition-all hover:bg-white hover:text-black hover:scale-[1.02] transform-gpu disabled:opacity-50 shadow-[0_0_20px_rgba(0,245,160,0.2)]"
            >
              {loading ? "Calculating Lead..." : "Secure My Stash"}
            </button>
          </motion.div>
        ) : (
          <motion.div
            key="success"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="w-full max-w-lg bg-white/5 backdrop-blur-2xl border border-student-primary/30 rounded-3xl p-10 shadow-[0_0_50px_-12px_rgba(0,245,160,0.2)] text-center"
          >
            <div className="w-20 h-20 bg-student-primary/20 rounded-full flex items-center justify-center mx-auto mb-6 border border-student-primary/40">
              <svg
                className="w-10 h-10 text-student-primary"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M5 13l4 4L19 7"
                />
              </svg>
            </div>
            <h2
              className="text-3xl font-bold text-white mb-4"
              style={{ fontFamily: "GTA6-Heading" }}
            >
              Stash Secured
            </h2>
            <p className="text-white/70 mb-8 leading-relaxed">
              Your savings have been locked in the matrix. Our logistics team will contact you
              shortly.
            </p>
            <button
              onClick={() => setIsSubmitted(false)}
              className="px-6 py-3 bg-white/10 text-white font-semibold rounded-lg hover:bg-white/20 transition-colors w-full"
            >
              Recalculate Matrix
            </button>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

// Premium Framer Motion Fluid Slider Component
function FramerSlider({
  label,
  min,
  max,
  value,
  onChange,
  suffix,
}: {
  label: string;
  min: number;
  max: number;
  value: number;
  onChange: (val: number) => void;
  suffix: string;
}) {
  const trackRef = useRef<HTMLDivElement>(null);

  const updateValue = (clientX: number) => {
    if (!trackRef.current) return;
    const { left, width } = trackRef.current.getBoundingClientRect();
    const percent = Math.max(0, Math.min(1, (clientX - left) / width));
    const newValue = Math.round(min + percent * (max - min));
    onChange(newValue);
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    // Prevent default to stop scrolling on mobile while sliding
    e.preventDefault();
    updateValue(e.clientX);

    const handlePointerMove = (ev: PointerEvent) => {
      ev.preventDefault();
      updateValue(ev.clientX);
    };

    const handlePointerUp = () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", handlePointerUp);
    };

    window.addEventListener("pointermove", handlePointerMove, { passive: false });
    window.addEventListener("pointerup", handlePointerUp);
  };

  const percentage = ((value - min) / (max - min)) * 100;

  return (
    <div>
      <div className="flex justify-between mb-3">
        <label className="text-sm font-medium text-white/80">{label}</label>
        <span className="text-sm font-bold text-student-primary bg-student-primary/10 px-2 py-1 rounded-md">
          {value}
          {suffix}
        </span>
      </div>
      <div
        ref={trackRef}
        className="relative h-3 bg-white/10 rounded-full cursor-pointer touch-none"
        onPointerDown={handlePointerDown}
      >
        {/* Animated Fill Track */}
        <motion.div
          className="absolute top-0 left-0 h-full bg-student-primary rounded-full pointer-events-none"
          animate={{ width: `${percentage}%` }}
          transition={{ type: "spring", stiffness: 500, damping: 40 }}
        />
        {/* Animated Knob */}
        <motion.div
          className="absolute top-1/2 -mt-3 -ml-3 w-6 h-6 bg-[#0a0a0a] rounded-full shadow-[0_0_15px_rgba(0,245,160,0.6)] cursor-grab active:cursor-grabbing border-2 border-student-primary flex items-center justify-center pointer-events-none"
          animate={{ left: `${percentage}%` }}
          transition={{ type: "spring", stiffness: 500, damping: 40 }}
        >
          <div className="w-2 h-2 bg-student-primary rounded-full shadow-[0_0_5px_rgba(0,245,160,0.8)]" />
        </motion.div>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import { motion, Variants } from "framer-motion";
import { supabase } from "@/lib/supabase";
import { useAuthStore } from "@/store/useAuthStore";

interface ActiveStash {
  id: string;
  items: number;
  status: string;
  created_at: string;
}

// Cinematic Reveal Variants
const containerVariants: Variants = {
  hidden: { opacity: 0 },
  show: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1, // 0.1s delay between each card cascading
      delayChildren: 0.15,
    },
  },
};

const itemVariants: Variants = {
  hidden: { opacity: 0, y: 20 },
  show: { opacity: 1, y: 0, transition: { type: "spring", stiffness: 400, damping: 30 } },
};

export function StashVault() {
  const { user } = useAuthStore();
  const [stashes, setStashes] = useState<ActiveStash[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchStashes = async () => {
      // Return early if no user is authenticated
      if (!user) {
        setLoading(false);
        return;
      }

      try {
        // RLS Consideration: The policy should only allow users to select rows where auth.uid() = user_id
        const { data, error } = await supabase
          .from("stash_leads")
          .select("*")
          .eq("user_id", user.id)
          .order("created_at", { ascending: false });

        if (error) throw error;

        // Map data to Vault UI structure

        const activeStashes = (data || []).map((lead: any) => ({
          id: lead.id,
          items: lead.items,
          status: "Secured at Host Facility",
          created_at: lead.created_at,
        }));

        setStashes(activeStashes);
      } catch (err) {
        console.error("Vault Synchronization Error:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchStashes();
  }, [user]);

  if (loading) {
    return (
      <div className="w-full min-h-[60vh] bg-transparent flex flex-col items-center justify-center relative z-10 p-6">
        <div className="w-full max-w-5xl grid grid-cols-1 md:grid-cols-3 gap-6">
          {[1, 2, 3].map((i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0.2 }}
              animate={{ opacity: 0.6 }}
              transition={{
                repeat: Infinity,
                duration: 1.2,
                repeatType: "reverse",
                ease: "easeInOut",
              }}
              className="h-[250px] bg-white/5 backdrop-blur-2xl border border-white/10 rounded-3xl shadow-lg"
            />
          ))}
        </div>
      </div>
