              </div>
              <DialogTitle className="text-lg font-bold">
                {isHi
                  ? "📱 एंड्रॉइड गो डिवाइस परफॉर्मेंस व क्रैश-सेफ्टी ऑडिट"
                  : "📱 Android Go & Low-Spec Device Performance Guard"}
              </DialogTitle>
            </div>
            {report && (
