                <ShieldCheck className="h-3.5 w-3.5 text-emerald-400" />
                {isHi
                  ? "5-बिंदु परफॉर्मेंस व क्रैश-सुरक्षा मैट्रिक्स"
                  : "5-Point Crash-Safety Audit Matrix"}
              </h4>
              <div className="space-y-2">
                {report.assertions.map((item) => (
                  <div
