import { runApiPenTest, type PenTestReport, type VectorAuditResult } from "@/lib/apiPenTestEngine";

interface ApiPenTestModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function ApiPenTestModal({ isOpen, onClose }: ApiPenTestModalProps) {
  const [report, setReport] = useState<PenTestReport | null>(null);
  const [isTesting, setIsTesting] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>("all");

  const executeTest = async () => {
    setIsTesting(true);
    try {
      const res = await runApiPenTest();
      setReport(res);
    } catch (err) {
      console.error("PenTest Execution Failed:", err);
    } finally {
      setIsTesting(false);
    }
  };

  useEffect(() => {
    if (isOpen && !report) {
      executeTest();
    }
  }, [isOpen, report]);

  if (!isOpen) return null;

  const exportReportJson = () => {
    if (!report) return;
    const blob = new Blob([JSON.stringify(report, null, 2)], {
      type: "application/json",
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `SS-API-PENTEST-REPORT-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const filteredVectors = report
    ? report.vectorResults.filter(
        (v) => selectedCategory === "all" || v.category === selectedCategory,
      )
    : [];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="relative w-full max-w-4xl max-h-[90vh] overflow-hidden rounded-3xl border border-rose-500/30 bg-[#0A0D0F] shadow-2xl flex flex-col text-foreground">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-white/10 bg-white/[0.02]">
          <div className="flex items-center gap-3">
