        </div>

        {/* Content Body */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {/* Top Score Banner */}
          {report && (
            <div className="rounded-2xl border border-emerald-500/30 bg-emerald-500/10 p-5 flex flex-col md:flex-row items-center justify-between gap-4">
              <div className="flex items-center gap-4">
                <div className="relative h-16 w-16 rounded-2xl bg-emerald-500/20 border border-emerald-500/40 flex items-center justify-center shrink-0 font-extrabold text-2xl text-emerald-400">
                  {report.overallScore}%
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <ShieldCheck className="h-5 w-5 text-emerald-400" />
                    <span className="font-bold text-base text-foreground">
                      {report.isCompliant
                        ? "API Endpoints 100% Pen-Test Verified"
                        : "Security Vulnerabilities Detected"}
                    </span>
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5">{report.summaryMessage}</p>
