export const FAQ = memo(function FAQ() {

  const { language, t } = useLanguage();
  const isHi = language === "hi";
  const [search, setSearch] = useState("");
  const [activeCategory, setActiveCategory] = useState<string>("transparency");

  const categories = [
    {
      id: "transparency",
      label: isHi ? "🔍 पूर्ण पारदर्शिता एवं कठिन प्रश्न" : "🔍 Radical Transparency",
    },
    { id: "all", label: isHi ? "सभी प्रश्न" : "All Questions" },
    { id: "storage", label: isHi ? "📦 छात्र स्टोरेज" : "📦 Student Storage" },
    { id: "safety", label: isHi ? "🛡️ सुरक्षा व ₹10k क्लेम" : "🛡️ Safety & Claims" },
    { id: "host", label: isHi ? "🏡 सीनियर होस्ट नियम" : "🏡 Verified PG Owner Host Norms" },
  ];

  const filteredFaqs = useMemo(() => {
    return FAQ_ITEMS.filter((faq) => {
      const matchesCategory = activeCategory === "all" || faq.category === activeCategory;
      const q = isHi && faq.question_hi ? faq.question_hi : faq.question;
      const a = isHi && faq.answer_hi ? faq.answer_hi : faq.answer;
      const matchesSearch =
        search.trim() === "" ||
        q.toLowerCase().includes(search.toLowerCase()) ||
        a.toLowerCase().includes(search.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [search, activeCategory, isHi]);

  const getCategoryCount = (catId: string) => {
    if (catId === "all") return FAQ_ITEMS.length;
    return FAQ_ITEMS.filter((f) => f.category === catId).length;
  };

  return (
    <section id="faq" className="relative px-4 py-4 sm:py-6 scroll-mt-20">
      <div className="mx-auto max-w-3xl">
        <AnimatedContent distance={20} direction="vertical" duration={0.5}>
          <div className="text-center mb-4">
            <Badge
              variant="outline"
              className="border-cyan-500/30 bg-cyan-500/10 text-[9.5px] sm:text-[11px] font-semibold uppercase tracking-widest text-cyan-400 font-mono mb-1.5"
            >
              {isHi ? "❓ स्पष्ट एवं ईमानदार उत्तर" : "❓ HONEST & UNFILTERED ANSWERS"}
            </Badge>

            <h2 className="text-xl sm:text-2xl lg:text-3xl font-extrabold tracking-tight text-foreground">
              {isHi ? (
                <>
                  अक्सर पूछे जाने वाले <span className="text-gradient">पारदर्शी सवाल</span>
                </>
              ) : (
                <>
                  Radical Transparency <span className="text-gradient">& Hard Questions</span>
                </>
              )}
            </h2>
            <p className="mt-1 text-xs text-muted-foreground max-w-xl mx-auto leading-relaxed">
              {isHi
                ? "बिना किसी कॉर्पोरेट घुमाव के — डेटा सुरक्षा, शुरुआती चरण की विश्वसनीयता और प्रत्यक्ष मानवीय जवाबदेही पर सीधे उत्तर।"
                : "Zero corporate spin. Direct answers addressing data privacy, early-stage reliability, and guaranteed human accountability."}
            </p>
          </div>

          {/* Search Input & Category Pills */}
          <div className="mb-3 space-y-2">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-slate-400" />
              <Input
                type="text"
                placeholder={
                  isHi
                    ? "कोई भी प्रश्न खोजें (उदा. डेटा सुरक्षा, क्लेम, नोड्स, एस्क्रो)..."
                    : "Search any question (e.g. data safety, claims, reliability, escrow)..."
                }
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-8 pr-3 py-2 h-9 rounded-xl border border-white/[0.08] bg-white/[0.025] hover:border-white/[0.14] backdrop-blur-md text-xs text-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-emerald-500/80 transition-all"
              />
            </div>

            <div className="flex flex-wrap items-center justify-center gap-1.5">
              {categories.map((cat) => {
                const count = getCategoryCount(cat.id);
                const isActive = activeCategory === cat.id;
                return (
                  <button
                    key={cat.id}
                    onClick={() => setActiveCategory(cat.id)}
                    className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-semibold tracking-[0.02em] transition-all cursor-pointer active:scale-[0.98] focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-cyan-400/80 focus-visible:ring-offset-1 focus-visible:ring-offset-[#0A0D0F] ${
                      isActive
                        ? "border border-cyan-500/40 bg-cyan-500/15 text-cyan-300 shadow-sm"
                        : "border border-white/[0.08] bg-white/[0.03] text-slate-400 hover:border-white/[0.16] hover:bg-white/[0.06] hover:text-white"
                    }`}
                  >
                    <span>{cat.label}</span>
                    <span
                      className={`text-[9px] font-mono px-1.5 py-0.2 rounded-full ${
                        isActive ? "bg-cyan-500/25 text-cyan-300" : "bg-white/10 text-slate-400"
                      }`}
                    >
                      {count}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          <div className="glass rounded-2xl border border-white/[0.08] p-3.5 sm:p-4 shadow-2xl">
            {filteredFaqs.length > 0 ? (
              <Accordion
                type="single"
                collapsible
                defaultValue="item-0"
                className="w-full space-y-2"
              >
                {filteredFaqs.map((faq, index) => (
                  <AccordionItem
                    key={index}
                    value={`item-${index}`}
                    className="border border-white/[0.06] bg-white/[0.02] rounded-xl px-4 overflow-hidden transition-all hover:border-white/[0.12] hover:bg-white/[0.035]"
                  >
                    <AccordionTrigger className="text-left font-semibold text-xs sm:text-sm hover:no-underline py-2.5 text-foreground/95 active:scale-[0.99] transition-transform">
                      {isHi && faq.question_hi ? faq.question_hi : faq.question}
                    </AccordionTrigger>
                    <AccordionContent className="text-xs text-muted-foreground leading-relaxed pb-3 pt-0.5">
                      {isHi && faq.answer_hi ? faq.answer_hi : faq.answer}
                    </AccordionContent>
                  </AccordionItem>
                ))}
              </Accordion>
            ) : (
              <div className="py-6 text-center text-muted-foreground text-xs">
                <Sparkles className="h-5 w-5 mx-auto mb-1.5 text-cyan-400 opacity-60" />
                {isHi ? (
                  <>
                    &ldquo;{search}&rdquo; के लिए कोई प्रश्न नहीं मिला। आप हमारे संस्थापक से सीधे
                    WhatsApp पर पूछ सकते हैं।
                  </>
                ) : (
                  <>
                    No matching questions found for &ldquo;{search}&rdquo;. You can ask our founder
                    directly on WhatsApp.
                  </>
                )}
              </div>
            )}
          </div>
        </AnimatedContent>
      </div>
    </section>
  );
});

