      {/* ── Metrics Cards Grid ── */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
        {/* Card 1: Total Box Capacity */}
        <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-3.5 relative overflow-hidden">
