  if (compact) {
    return (
      <button
        type="button"
        onClick={onClick}
        className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-0.5 text-[11px] font-bold transition hover:scale-105 cursor-pointer ${config.bgColor} ${config.borderColor} ${config.color}`}
