        {/* Header Bar */}
        <div className="flex items-center justify-between p-5 border-b border-slate-800 bg-slate-900/60">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-400">
              <UserCheck className="w-6 h-6" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-xl font-bold text-white tracking-wide">
                  {isHi
                    ? "रिवर्स लॉजिस्टिक्स एवं प्रॉक्सी-हैंडओवर"
                    : "Reverse Logistics & Proxy-Handover Pass"}
                </h3>
                <span className="px-2.5 py-0.5 text-xs font-semibold rounded-full bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">
                  Task 131 QA
                </span>
              </div>
              <p className="text-xs text-slate-400 mt-0.5">
                {isHi
                  ? "सुरक्षित 2FA मित्र सामान वितरण एवं सत्यापन प्रणाली"
                  : "Secure 2FA Proxy Handover Protocol for Out-of-City Students"}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-white rounded-lg hover:bg-slate-800 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Navigation Tabs */}
        <div className="flex border-b border-slate-800 bg-slate-950/40 px-5 pt-3 gap-2">
          <button
            onClick={() => setActiveTab("authorize")}
            className={`flex items-center gap-2 px-4 py-2.5 text-sm font-medium border-b-2 transition-colors ${
              activeTab === "authorize"
                ? "border-emerald-400 text-emerald-400 bg-emerald-500/10 rounded-t-lg"
                : "border-transparent text-slate-400 hover:text-slate-200"
            }`}
          >
            <Key className="w-4 h-4" />
            {isHi ? "1. प्रॉक्सी अधिकृत करें" : "1. Authorize Proxy"}
          </button>
          <button
            onClick={() => setActiveTab("verify")}
            className={`flex items-center gap-2 px-4 py-2.5 text-sm font-medium border-b-2 transition-colors ${
              activeTab === "verify"
