    playClick();

    setTimeout(() => {
      const res = claimZeroFeeTrialToken(phone, college);
      setIsVerifying(false);

      if (res.success) {
        setWallet(res.wallet);
        setClaimSuccess(true);
        toast.success(res.message);
        playPop();
      } else {
        toast.info(res.message);
      }
