          <DialogTitle className="text-xl font-bold text-white tracking-tight">
            {isHi ? "⚡ ₹60 जीरो-फी ट्रायल टोकन क्लेम करें" : "⚡ Claim ₹60 Zero-Fee Trial Token"}
