                      {isHi && step.detail_hi ? step.detail_hi : step.detail}
                    </p>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </AnimatedContent>

      <AnimatePresence>
        {showCert && <SealCertificate onClose={() => setShowCert(false)} />}
      </AnimatePresence>
    </div>
  );
}

