import React, { createContext, useContext, useEffect, useState, useMemo, useCallback } from "react";
import { toast } from "sonner";

export interface LowDataContextType {
  isLowData: boolean;
  toggleLowData: () => void;
  setLowData: (enabled: boolean) => void;
  isAutoDetected: boolean;
  effectiveType: string;
}

const LowDataContext = createContext<LowDataContextType | undefined>(undefined);

/**
 * Checks if the browser is currently running under a low-bandwidth connection (2G/3G/Save-Data).
 */
export function detectLowDataConnection(): { isSlow: boolean; type: string; saveData: boolean } {
  if (typeof window === "undefined" || typeof navigator === "undefined") {
    return { isSlow: false, type: "unknown", saveData: false };
  }

  const nav = navigator as any;
  const connection = nav.connection || nav.mozConnection || nav.webkitConnection;

  if (!connection) {
    return { isSlow: false, type: "unknown", saveData: false };
  }

  const saveData = Boolean(connection.saveData);
  const type = connection.effectiveType || "unknown";
  const isSlow = saveData || type === "2g" || type === "slow-2g" || type === "3g";

  return { isSlow, type, saveData };
}

/**
 * Global Low-Data Mode Provider.
 * Automatically detects weak 2G/3G/save-data connections,
 * syncs state with `localStorage` (`ss_low_data_mode`),
 * and updates DOM attributes on `document.documentElement` to disable GSAP/WebGL animations.
 */
export function LowDataProvider({ children }: { children: React.ReactNode }) {
  const [isLowData, setIsLowDataState] = useState<boolean>(() => {
    if (typeof window !== "undefined") {
      try {
        const saved = localStorage.getItem("ss_low_data_mode");
        if (saved !== null) return saved === "true";
        return detectLowDataConnection().isSlow;
      } catch (e) {
        console.debug("Failed to read ss_low_data_mode from localStorage", e);
      }
    }
    return false;
  });
  const [isAutoDetected, setIsAutoDetected] = useState<boolean>(() => {
    if (typeof window !== "undefined") {
      try {
        if (localStorage.getItem("ss_low_data_mode") === null) {
          return detectLowDataConnection().isSlow;
        }
      } catch (e) {
        console.debug("Failed to read ss_low_data_mode from localStorage", e);
      }
    }
    return false;
  });
  const [effectiveType, setEffectiveType] = useState<string>(() => {
    return detectLowDataConnection().type;
  });

  const applyLowDataDOM = useCallback((enabled: boolean) => {
    if (typeof document === "undefined") return;

    const root = document.documentElement;
    root.setAttribute("data-low-data-mode", enabled ? "true" : "false");

    if (enabled) {
      root.classList.add("low-data-mode");
      root.classList.add("legacy-android-fallback");
      root.setAttribute("data-webgl-supported", "false");
    } else {
      root.classList.remove("low-data-mode");
      // Only remove fallback if legacy android guard didn't set it
      if (root.getAttribute("data-legacy-android") !== "true") {
        root.classList.remove("legacy-android-fallback");
        root.setAttribute("data-webgl-supported", "true");
      }
    }
  }, []);

  useEffect(() => {
    if (typeof window === "undefined") return;

    const detection = detectLowDataConnection();
    setEffectiveType(detection.type);

    try {
      const saved = localStorage.getItem("ss_low_data_mode");
      if (saved !== null) {
        const enabled = saved === "true";
        setIsLowDataState(enabled);
        setIsAutoDetected(false);
        applyLowDataDOM(enabled);
      } else {
        // Auto-detect based on connection
        if (detection.isSlow) {
          setIsLowDataState(true);
          setIsAutoDetected(true);
          applyLowDataDOM(true);
          toast.info("Low-Data Mode Auto-Enabled", {
            description: `Detected weak network (${detection.type.toUpperCase()}). Animations disabled & static images enabled to conserve cellular data.`,
            duration: 5000,
          });
        } else {
          setIsLowDataState(false);
          setIsAutoDetected(false);
          applyLowDataDOM(false);
        }
      }
    } catch {
      applyLowDataDOM(false);
    }

    // Listen to connection changes if supported

    const nav = typeof navigator !== "undefined" ? (navigator as any) : null;
    const connection = nav ? nav.connection || nav.mozConnection || nav.webkitConnection : null;

    if (!connection) return;

    const handleConnectionChange = () => {
      const updated = detectLowDataConnection();
      setEffectiveType(updated.type);
      const saved = localStorage.getItem("ss_low_data_mode");
      if (saved === null && updated.isSlow) {
        setIsLowDataState(true);
        setIsAutoDetected(true);
        applyLowDataDOM(true);
      }
    };

    connection.addEventListener("change", handleConnectionChange);
    return () => {
      connection.removeEventListener("change", handleConnectionChange);
    };
  }, [applyLowDataDOM]);

  const setLowData = useCallback(
    (enabled: boolean) => {
      setIsLowDataState(enabled);
      setIsAutoDetected(false);
      applyLowDataDOM(enabled);

      try {
        localStorage.setItem("ss_low_data_mode", enabled ? "true" : "false");
      } catch {
        // Ignore storage error
      }

      if (enabled) {
        toast.success("Low-Data Mode Activated", {
          description:
            "GSAP & WebGL animations disabled, lightweight static images enabled for maximum performance.",
          duration: 3500,
        });
      } else {
        toast.info("Standard Performance Mode Restored", {
          description: "Full kinetic 120 FPS animations & 3D WebGL canvases re-enabled.",
          duration: 3000,
        });
      }
    },
    [applyLowDataDOM],
  );

  const toggleLowData = useCallback(() => {
    setLowData(!isLowData);
  }, [isLowData, setLowData]);

  const contextValue = useMemo(
    () => ({
      isLowData,
      toggleLowData,
      setLowData,
      isAutoDetected,
      effectiveType,
    }),
    [isLowData, toggleLowData, setLowData, isAutoDetected, effectiveType],
  );

  return <LowDataContext.Provider value={contextValue}>{children}</LowDataContext.Provider>;
}

const defaultContext: LowDataContextType = {
  isLowData: false,
  toggleLowData: () => {},
  setLowData: () => {},
  isAutoDetected: false,
  effectiveType: "unknown",
};

/**
 * Hook to access the global low-data mode state.
 */
export function useLowData(): LowDataContextType {
  const context = useContext(LowDataContext);
  return context || defaultContext;
}

/**
 * Direct non-react checker for utility functions and non-react modules.
 */
export function isLowDataModeEnabled(): boolean {
  if (typeof document === "undefined") return false;
  return document.documentElement.getAttribute("data-low-data-mode") === "true";
}

import React, { createContext, useContext, useEffect, useState, useMemo, useCallback } from "react";

export type Theme = "dark" | "light";

type ThemeContextType = {
  theme: Theme;
  toggleTheme: () => void;
  setTheme: (theme: Theme) => void;
  isDark: boolean;
};

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

/**
 * Global Theme Provider — modified to enforce dark mode only.
 */
export function ThemeProvider({ children }: { children: React.ReactNode }) {

  const [theme] = useState<Theme>("dark");

  useEffect(() => {
    if (typeof window !== "undefined") {
      const root = document.documentElement;
      root.dataset["theme"] = "dark";
      root.classList.add("dark");
      root.classList.remove("light");

      // Update meta theme-color tag
      const metaThemeColor = document.querySelector('meta[name="theme-color"]');
      if (metaThemeColor) {
        metaThemeColor.setAttribute("content", "#0A0D0F");
      }
    }
  }, []);

  const setTheme = useCallback((t: Theme) => {}, []);
  const toggleTheme = useCallback(() => {}, []);

  const contextValue = useMemo(
    () => ({
      theme: "dark" as Theme,
      toggleTheme,
      setTheme,
      isDark: true,
    }),
    [toggleTheme, setTheme],
  );

  return <ThemeContext.Provider value={contextValue}>{children}</ThemeContext.Provider>;
}

const defaultContextValue: ThemeContextType = {
  theme: "dark",
  toggleTheme: () => {},
  setTheme: () => {},
  isDark: true,
};

/**
 * Hook to access the global theme state.
 */
export function useTheme() {
  const context = useContext(ThemeContext);
  return context || defaultContextValue;
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import { jwtDecode } from "jwt-decode";
import { toast } from "sonner";
import type { CredentialResponse } from "@react-oauth/google";
import { upsertGoogleUser } from "@/lib/waitlistService";
import { supabase } from "@/lib/supabase";
import { useAuthStore } from "@/store/useAuthStore";

export type AuthUser = {
  id: string;
  name: string;
  email: string;
  avatar: string;
  role: "student" | "host";
  verified: boolean;
  provider?: "google" | "local";
  phone_number?: string;
  college_or_locality?: string;
  bio?: string;
  address?: string;
  emergency_contact?: string;
};

type AuthValue = {
  user: AuthUser | null;
  loading: boolean;
  authenticating: boolean;
  loginWithGoogle: (
    response: CredentialResponse,
    defaultRole?: "student" | "host",
  ) => Promise<void>;
  loginWithProfile: (profile: AuthUser) => void;
  updateUser: (updates: Partial<AuthUser>) => void;
  logout: () => void;
  setAuthenticating: (val: boolean) => void;
};

const AuthContext = createContext<AuthValue | null>(null);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [userLocal, setUserLocal] = useState<AuthUser | null>(null);
  const [loadingLocal, setLoadingLocal] = useState(true);
  const [authenticating, setAuthenticating] = useState(false);

  // Single source of truth from Supabase
  const supabaseUser = useAuthStore((state) => state.user);
  const isLoadingSupabase = useAuthStore((state) => state.isLoading);

  useEffect(() => {
    // Load local override for mock users from localStorage
    const storedUser = localStorage.getItem("stash_user_session");
    if (storedUser) {
      try {
        setUserLocal(JSON.parse(storedUser));

      } catch (e) {
        localStorage.removeItem("stash_user_session");
      }
    }
    setLoadingLocal(false);
  }, []);

  // Compute derived user state: Supabase takes precedence over local mock
  const user = useMemo<AuthUser | null>(() => {
    if (supabaseUser) {
      return {
        id: supabaseUser.id,
        email: supabaseUser.email || "",
        name:
          supabaseUser.user_metadata?.["full_name"] || supabaseUser.email?.split("@")[0] || "User",
        avatar: supabaseUser.user_metadata?.["avatar_url"] || "",
        role: supabaseUser.user_metadata?.["role"] || "student",
        verified: !!supabaseUser.email_confirmed_at,
        provider: supabaseUser.app_metadata?.provider === "google" ? "google" : "local",
      };
    }
    return userLocal;
  }, [supabaseUser, userLocal]);

  const loading = loadingLocal || isLoadingSupabase;

  const loginWithGoogle = useCallback(
    async (response: CredentialResponse, defaultRole: "student" | "host" = "student") => {
      setAuthenticating(true);
      try {
        if (!response.credential) {
          throw new Error("No credential received from Google");
        }

        // Establish real Supabase session using the Google ID Token

        const { data, error } = await supabase.auth.signInWithIdToken({
          provider: "google",
          token: response.credential,
        });

        if (error) throw error;

        // Optionally update metadata if newly created
        await supabase.auth.updateUser({ data: { role: defaultRole } });

        const decoded = jwtDecode<{
          sub?: string;
          name?: string;
          email?: string;
          picture?: string;
          email_verified?: boolean;
        }>(response.credential);

        const userEmail = decoded.email;
        if (!userEmail) {
          throw new Error("Email not found in Google credential");
        }

        // Persist to Supabase users_waitlist (fire-and-forget)
        upsertGoogleUser({
          email: userEmail,
          name: decoded.name || userEmail.split("@")[0] || "User",
          picture: decoded.picture || "",
        });

        const firstName =
          (decoded.name || userEmail.split("@")[0] || "User").split(" ")[0] || "User";
        toast.success(`Welcome back, ${firstName}!`, {
          description: `Logged in as ${defaultRole === "student" ? "Student" : "High-Margin ROI Host"}`,
        });
      } catch (err) {
        console.error("Google Auth Error:", err);
        toast.error("Google sign-in failed", { description: "Please try again in a moment." });
      } finally {
        setAuthenticating(false);
      }
    },
    [],
  );

  const loginWithProfile = useCallback((newUser: AuthUser) => {
    // Local mock fallback for profile login
    setUserLocal(newUser);
    localStorage.setItem("stash_user_session", JSON.stringify(newUser));

    upsertGoogleUser({
      email: newUser.email,
      name: newUser.name,
      picture: newUser.avatar,
    });

    const firstName = newUser.name.split(" ")[0];
    toast.success(`Welcome back, ${firstName}!`, {
      description: `Logged in as ${newUser.role === "student" ? "Student" : "High-Margin ROI Host"}`,
    });
  }, []);

  const logout = useCallback(async () => {
    setUserLocal(null);
    localStorage.removeItem("stash_user_session");
    await supabase.auth.signOut();
    toast.success("Signed out. See you soon!");
  }, []);

  const updateUser = useCallback(
    async (updates: Partial<AuthUser>) => {
      setUserLocal((prev) => {
        if (!prev) return null;
        const updatedUser = { ...prev, ...updates };
        localStorage.setItem("stash_user_session", JSON.stringify(updatedUser));
        window.dispatchEvent(
          new CustomEvent("stashsaarthi:profile-updated", { detail: updatedUser }),
        );
        return updatedUser;
      });

      // Also update Supabase metadata if logged in via Supabase
      if (supabaseUser) {
        await supabase.auth.updateUser({ data: updates });
      }
    },
    [supabaseUser],
  );

  const value = useMemo(
    () => ({
      user,
      loading,
      authenticating,
      loginWithGoogle,
      loginWithProfile,
      updateUser,
      logout,
      setAuthenticating,
    }),
    [user, loading, authenticating, loginWithGoogle, loginWithProfile, updateUser, logout],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used inside <AuthProvider>");
  return ctx;
}

import { createClient } from "@supabase/supabase-js";
import type { Database } from "./types";

function createSupabaseClient() {
  // Use import.meta.env for client-side (Vite build-time replacement)
  // Fall back to process.env for SSR (server-side rendering)
  const SUPABASE_URL = import.meta.env["VITE_SUPABASE_URL"] || process.env["SUPABASE_URL"];
  const SUPABASE_PUBLISHABLE_KEY =
    import.meta.env["VITE_SUPABASE_PUBLISHABLE_KEY"] || process.env["SUPABASE_PUBLISHABLE_KEY"];

  if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
    const missing = [
      ...(!SUPABASE_URL ? ["SUPABASE_URL"] : []),
      ...(!SUPABASE_PUBLISHABLE_KEY ? ["SUPABASE_PUBLISHABLE_KEY"] : []),
    ];
    const message = `Missing Supabase environment variable(s): ${missing.join(", ")}. Falling back to simulated demo state.`;
    console.warn(`[Supabase] ${message}`);

    // Return a deeply mocked client that returns safe empty values instead of crashing

    const createMockObject = (): any => {
      const mockResult = Promise.resolve({ data: [], error: null, count: 0 });
      return new Proxy(() => createMockObject(), {
        get: (target, prop) => {
          if (prop === "then") return mockResult.then.bind(mockResult);
          if (prop === "catch") return mockResult.catch.bind(mockResult);
          if (prop === "finally") return mockResult.finally.bind(mockResult);
          return createMockObject();
        },
        apply: () => createMockObject(),
      });
    };
    return createMockObject() as ReturnType<typeof createClient<Database>>;
  }

  return createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
    auth: {
      storage: typeof window !== "undefined" ? localStorage : undefined,
      storageKey: "ss_supabase_auth_token",
      persistSession: true,
      autoRefreshToken: true,
      detectSessionInUrl: true,
      flowType: "pkce",
    },
    db: {
      // Explicit schema declaration: prevents PostgREST content negotiation overhead
      schema: "public",
    },
    global: {
      // 8-second global fetch timeout: prevents UI hangs on slow connections
      fetch: (url, options = {}) => {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 8000);
        return fetch(url, {
          ...options,
          signal: controller.signal,
        }).finally(() => clearTimeout(timeoutId));
      },
    },
    realtime: {
      // Realtime channels are not used in StashSaarthi frontend — disable to save connection overhead
      params: { eventsPerSecond: 0 },
    },
  });
}

let _supabase: ReturnType<typeof createSupabaseClient> | undefined;

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";
export const supabase = new Proxy({} as ReturnType<typeof createSupabaseClient>, {
  get(_, prop, receiver) {
    if (!_supabase) _supabase = createSupabaseClient();
    return Reflect.get(_supabase, prop, receiver);
  },
});

