"use client";

import { useState, useCallback, useEffect, lazy, Suspense, useRef } from "react";
import { createFileRoute } from "@tanstack/react-router";

import { motion, useScroll, useTransform } from "framer-motion";

import { AmbientNodes } from "@/components/ui/AmbientNodes";

import { ErrorBoundary } from "@/components/ui/ErrorBoundary";
import { usePersona } from "@/context/PersonaContext";
import type { BookingPrefill } from "@/components/stash/types";

import { HomeHeroSection } from "@/components/home/HomeHeroSection";
import { HomeSolutions } from "@/components/home/HomeSolutions";
import { HomeDeepModules } from "@/components/home/HomeDeepModules";
import { HomeFooterAndModals } from "@/components/home/HomeFooterAndModals";

const TITLE = "StashSaarthi - Campus Micro-Storage & Zero-Brokerage Co-Living";
const DESC =
  "Official website of StashSaarthi. India's Zero-CapEx Intergenerational Living & Campus Micro-Storage Platform. Vacation luggage storage at ₹300/bag/mo, verified verified PG owner-hosted rooms, and homemade tiffins.";
const URL = "https://stashsaarthi-web.vercel.app/";
const OG_IMAGE = "https://stashsaarthi-web.vercel.app/images/og-banner-new.png";

export const Route = createFileRoute("/")({
  head: () => ({
    meta: [
      { title: TITLE },
      { name: "description", content: DESC },
      { property: "og:title", content: "StashSaarthi" },
      { property: "og:site_name", content: "StashSaarthi" },
      { property: "og:description", content: DESC },
      { property: "og:type", content: "website" },
      { property: "og:url", content: URL },
      { property: "og:image", content: OG_IMAGE },
      { name: "twitter:card", content: "summary_large_image" },
      { name: "twitter:title", content: TITLE },
      { name: "twitter:description", content: DESC },
      { name: "twitter:image", content: OG_IMAGE },
    ],
    links: [{ rel: "canonical", href: URL }],
  }),
  component: Index,
});

function Index() {
  const { role, setRole } = usePersona();
  const [booking, setBooking] = useState(false);
  const [listing, setListing] = useState(false);
  const [earlyAccess, setEarlyAccess] = useState(false);
  const [referralOpen, setReferralOpen] = useState(false);
  const [prefill, setPrefill] = useState<BookingPrefill>({});

  const open = useCallback((p?: BookingPrefill) => {
    setPrefill(p ?? {});
    setBooking(true);
  }, []);

  const handleBookDefault = useCallback(() => {
    open();
  }, [open]);

  const handleListRoom = useCallback(() => setListing(true), []);
  const handleEarlyAccess = useCallback(() => setEarlyAccess(true), []);
  const handleRefer = useCallback(() => setReferralOpen(true), []);

  useEffect(() => {
    const handleOpenBooking = (e: Event) => {
      const customEv = e as CustomEvent<{ service?: string; promoCode?: string; note?: string }>;
      if (customEv.detail) {
        open({
          service: customEv.detail.service,
          note:
            customEv.detail.note ||
            (customEv.detail.promoCode
              ? `Applied Offer Code ${customEv.detail.promoCode}: Flat ₹50 Discount`
              : undefined),
        });
      } else {
        open();
      }
    };
    window.addEventListener("stashsaarthi:open-booking", handleOpenBooking);
    return () => window.removeEventListener("stashsaarthi:open-booking", handleOpenBooking);
  }, [open]);

  return (
    <motion.main
      id="main-content"
      tabIndex={-1}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
      transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
      className="relative min-h-screen w-full max-w-full overflow-x-clip bg-transparent text-white transition-colors duration-500 focus:outline-none pt-16 sm:pt-20 pb-24 sm:pb-0"
    >
      <a href="#main-content" className="skip-to-content">
        Skip to main content
      </a>

      <HomeHeroSection
        role={role}
        setRole={setRole}
        onBookDefault={handleBookDefault}
        onBook={open}
        onListRoom={handleListRoom}
        onEarlyAccess={handleEarlyAccess}
        onRefer={handleRefer}
      />

      <HomeSolutions onBook={open} onListRoom={handleListRoom} />

      <HomeDeepModules role={role} onBook={open} onRefer={handleRefer} />

      <HomeFooterAndModals
        role={role}
        booking={booking}
        setBooking={setBooking}
        listing={listing}
        setListing={setListing}
        earlyAccess={earlyAccess}
        setEarlyAccess={setEarlyAccess}
        referralOpen={referralOpen}
        setReferralOpen={setReferralOpen}
        prefill={prefill}
        onBook={open}
        onRefer={handleRefer}
      />
    </motion.main>
  );
}

// Supabase Edge Function: generate-invoice (Task 109)
// Generates GST-compliant PDF invoice bytes using pdf-lib on Deno / Supabase Edge Runtimes

// @ts-expect-error: Deno standard library URL import for Supabase Edge Runtime
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
// @ts-expect-error: Deno Skypack CDN import for Supabase Edge Runtime
import { PDFDocument, rgb, StandardFonts } from "https://cdn.skypack.dev/pdf-lib@1.17.1?dts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    const { booking } = await req.json();

    if (!booking || !booking.token) {
      return new Response(JSON.stringify({ error: "Booking record is required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const pdfDoc = await PDFDocument.create();
    const page = pdfDoc.addPage([595.28, 841.89]);
    const { width, height } = page.getSize();

    const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
    const fontHelvetica = await pdfDoc.embedFont(StandardFonts.Helvetica);

    const colorDark = rgb(0.04, 0.05, 0.06);
    const colorPrimary = rgb(0.06, 0.73, 0.51);

    page.drawRectangle({
      x: 0,
      y: height - 100,
      width: width,
      height: 100,
      color: colorDark,
    });

    page.drawText("STASHSAARTHI", {
      x: 40,
      y: height - 45,
      size: 22,
      font: fontBold,
      color: colorPrimary,
    });

    page.drawText("GST TAX INVOICE", {
      x: width - 180,
      y: height - 45,
      size: 16,
      font: fontBold,
      color: rgb(1, 1, 1),
    });

    page.drawText(`Invoice No: INV-2026-${booking.token.replace("#", "")}`, {
      x: 40,
      y: height - 140,
      size: 10,
      font: fontBold,
      color: colorDark,
    });

    page.drawText(`Customer: ${booking.name || "Student User"}`, {
      x: 40,
      y: height - 160,
      size: 10,
      font: fontHelvetica,
      color: colorDark,
    });

    page.drawText(`Total Amount Paid: INR ${booking.amount || 300}`, {
      x: 40,
      y: height - 180,
      size: 12,
      font: fontBold,
      color: colorPrimary,
    });

    const pdfBytes = await pdfDoc.save();

    return new Response(pdfBytes, {
      status: 200,
      headers: {
        ...corsHeaders,
        "Content-Type": "application/pdf",
        "Content-Disposition": `attachment; filename=Invoice_${booking.token}.pdf`,
      },
    });

  } catch (error: any) {
    return new Response(JSON.stringify({ error: error.message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});
